func (this *Gemini) fetchTickerV1AndV2Body(ch chan AsyncResult[Ticker], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	tickerPromiseA := this.FetchTickerV1Async(symbol, params)
	tickerPromiseB := this.FetchTickerV2Async(symbol, params)
	r := <-PromiseAllTyped[Ticker, AsyncResult[Ticker]](tickerPromiseA, tickerPromiseB)
	if r.Err != nil {
		panic(r.Err)
	}
	var tickerAtickerBVariable []map[string]any = StructSliceToMaps(r.Value, TickerToMap)
	var tickerA any = nil
	if tickerAtickerBVariable[0] != nil {
		tickerA = tickerAtickerBVariable[0]
	}
	var tickerB any = nil
	if tickerAtickerBVariable[1] != nil {
		tickerB = tickerAtickerBVariable[1]
	}

	ch <- AsyncResult[Ticker]{Value: TickerFromMap(this.DeepExtend(tickerA, map[string]any{
		"open":       this.SafeString(tickerB, "open"),
		"high":       this.SafeString(tickerB, "high"),
		"low":        this.SafeString(tickerB, "low"),
		"change":     this.SafeString(tickerB, "change"),
		"percentage": this.SafeString(tickerB, "percentage"),
		"average":    this.SafeString(tickerB, "average"),
		"info":       this.SafeValue(tickerB, "info"),
	}))}
	return nil
}

/**
 * @method
 * @name gemini#fetchTicker
 * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
 * @see https://docs.gemini.com/rest-api/#ticker
 * @see https://docs.gemini.com/rest-api/#ticker-v2
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {object} [params.fetchTickerMethod] 'fetchTickerV2', 'fetchTickerV1' or 'fetchTickerV1AndV2' - 'fetchTickerV1' for original ccxt.gemini.fetchTicker - 'fetchTickerV1AndV2' for 2 api calls to get the result of both fetchTicker methods - default = 'fetchTickerV1'
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Gemini) FetchTickerAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[Ticker] {
	ch := make(chan AsyncResult[Ticker], 1)
	go this.fetchTickerBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Gemini) fetchTickerBody(ch chan AsyncResult[Ticker], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var method string = *this.SafeString(this.Options, "fetchTickerMethod", "fetchTickerV1")
	if method == "fetchTickerV1" {

		r := <-this.FetchTickerV1Async(symbol, params)
		if r.Err != nil {
			panic(r.Err)
		}
		ch <- AsyncResult[Ticker]{Value: r.Value}
		return nil
	}
	if method == "fetchTickerV2" {

		r1 := <-this.FetchTickerV2Async(symbol, params)
		if r1.Err != nil {
			panic(r1.Err)
		}
		ch <- AsyncResult[Ticker]{Value: r1.Value}
		return nil
	}

	r2 := <-this.FetchTickerV1AndV2Async(symbol, params)
	if r2.Err != nil {
		panic(r2.Err)
	}
	ch <- AsyncResult[Ticker]{Value: r2.Value}
	return nil
}
func (this *Gemini) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	// fetchTickers
	//
	//     {
	//         "pair": "BATUSD",
	//         "price": "0.20687",
	//         "percentChange24h": "0.0146"
	//     }
	//
	// fetchTickerV1
	//
	//     {
	//         "bid":"9117.95",
	//         "ask":"9117.96",
	//         "volume":{
	//             "BTC":"1615.46861748",
	//             "USD":"14727307.57545006088",
	//             "timestamp":1594982700000
	//         },
	//         "last":"9115.23"
	//     }
	//
	// fetchTickerV2
	//
	//     {
	//         "symbol":"BTCUSD",
	//         "open":"9080.58",
	//         "high":"9184.53",
	//         "low":"9063.56",
	//         "close":"9116.08",
	//         // Hourly prices descending for past 24 hours
	//         "changes":["9117.33","9105.69","9106.23","9120.35","9098.57","9114.53","9113.55","9128.01","9113.63","9133.49","9133.49","9137.75","9126.73","9103.91","9119.33","9123.04","9124.44","9117.57","9114.22","9102.33","9076.67","9074.72","9074.97","9092.05"],
	//         "bid":"9115.86",
	//         "ask":"9115.87"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var volume map[string]any = SafeMapTyped(ticker, "volume")
	var timestamp *int64 = this.SafeInteger(volume, "timestamp")
	var symbol any = nil
	var marketId *string = this.SafeStringLower(ticker, "pair")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var baseId any = nil
	var quoteId any = nil
	var base *string = nil
	var quote *string = nil
	if (marketId != nil) && (marketResolved == nil) {
		var idLength int64 = int64(GetLength(marketId)) - 0
		if idLength == 7 {
			baseId = func() string {
				if marketId == nil {
					return ""
				}
				str := *marketId
				return str[0:min(4, len(str))]
			}()
			quoteId = func() string {
				if marketId == nil {
					return ""
				}
				str := *marketId
				return str[4:min(7, len(str))]
			}()
		} else {
			baseId = func() string {
				if marketId == nil {
					return ""
				}
				str := *marketId
				return str[0:min(3, len(str))]
			}()
			quoteId = func() string {
				if marketId == nil {
					return ""
				}
				str := *marketId
				return str[3:min(6, len(str))]
			}()
		}
		base = this.SafeCurrencyCode(baseId)
		quote = this.SafeCurrencyCode(quoteId)
		if (base != nil) && (quote != nil) {
			symbol = *base + "/" + *quote
		}
	}
	if (symbol == nil) && (marketResolved != nil) {
		symbol = marketResolved["symbol"]
		baseId = this.SafeStringUpper(marketResolved, "baseId")
		quoteId = this.SafeStringUpper(marketResolved, "quoteId")
	}
	var price *string = this.SafeString(ticker, "price")
	var last *string = this.SafeString2(ticker, "last", "close", price)
	var percentage *string = this.SafeString(ticker, "percentChange24h")
	var open *string = this.SafeString(ticker, "open")
	var baseVolume *string = this.SafeString(volume, baseId)
	var quoteVolume *string = this.SafeString(volume, quoteId)
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          open,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    percentage,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   quoteVolume,
		"info":          ticker,
	}, marketResolved)
}

