/**
 * @method
 * @name gemini#createOrder
 * @description create a trade order
 * @see https://docs.gemini.com/rest-api/#new-order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type must be 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Gemini) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Gemini) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	if typeVar != "limit" {
		panic(ExchangeError(this.Id + " createOrder() allows limit orders only"))
	}
	var clientOrderId *string = this.SafeString2(params, "clientOrderId", "client_order_id")
	if clientOrderId == nil {
		clientOrderId = SafeStringPtr(strconv.FormatInt(this.Milliseconds(), 10))
	}
	var market map[string]any = this.Market(symbol)
	var amountString *string = this.AmountToPrecision(symbol, amount)
	var priceString *string = this.PriceToPrecision(symbol, price)
	var request map[string]any = map[string]any{
		"client_order_id": clientOrderId,
		"symbol":          market["id"],
		"amount":          amountString,
		"price":           priceString,
		"side":            side,
		"type":            "exchange limit",
	}
	var typeValue *string = this.SafeString(params, "type", typeVar)
	var triggerPrice *string = this.SafeStringN(params, []any{"triggerPrice", "stop_price", "stopPrice"})
	// timeInForce and postOnly are consumed only by non-trigger orders
	var omitKeys []any = []any{"clientOrderId", "client_order_id", "type", "triggerPrice", "stop_price", "stopPrice"}
	var optionKeys []any = []any{}
	if triggerPrice == nil {
		optionKeys = []any{"timeInForce", "postOnly"}
	}
	var paramsOmitted map[string]any = this.OmitDict(params, this.ArrayConcat(omitKeys, optionKeys))
	if typeValue != nil && *typeValue == "stopLimit" {
		panic(ArgumentsRequired(this.Id + " createOrder() requires a triggerPrice parameter or a stop_price parameter for " + *typeValue + " orders"))
	}
	if triggerPrice != nil {
		request["stop_price"] = this.PriceToPrecision(symbol, triggerPrice)
		request["type"] = "exchange stop limit"
	} else {
		// No options can be applied to stop-limit orders at this time.
		var timeInForce *string = this.SafeString(params, "timeInForce")
		if timeInForce != nil {
			if (timeInForce != nil && *timeInForce == "IOC") || (timeInForce != nil && *timeInForce == "immediate-or-cancel") {
				request["options"] = []any{"immediate-or-cancel"}
			} else if (timeInForce != nil && *timeInForce == "FOK") || (timeInForce != nil && *timeInForce == "fill-or-kill") {
				request["options"] = []any{"fill-or-kill"}
			} else if timeInForce != nil && *timeInForce == "PO" {
				request["options"] = []any{"maker-or-cancel"}
			}
		}
		var postOnly *bool = this.SafeBool(params, "postOnly", false)
		if postOnly != nil && *postOnly {
			request["options"] = []any{"maker-or-cancel"}
		}
		// allowing override for auction-only and indication-of-interest order options
		var options *string = this.SafeString(params, "options")
		if options != nil {
			request["options"] = []any{options}
		}
	}

	r1 := <-this.PrivatePostV1OrderNew(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//      {
	//          "order_id":"106027397702",
	//          "id":"106027397702",
	//          "symbol":"etheur",
	//          "exchange":"gemini",
	//          "avg_execution_price":"2877.48",
	//          "side":"sell",
	//          "type":"exchange limit",
	//          "timestamp":"1650398122",
	//          "timestampms":1650398122308,
	//          "is_live":false,
	//          "is_cancelled":false,
	//          "is_hidden":false,
	//          "was_forced":false,
	//          "executed_amount":"0.014434",
	//          "client_order_id":"1650398121695",
	//          "options":[],
	//          "price":"2800.00",
	//          "original_amount":"0.014434",
	//          "remaining_amount":"0"
	//      }
	//
	ch <- AsyncResult[Order]{Value: this.ParseOrder(response)}
	return nil
}

