/**
 * @method
 * @name gemini#withdraw
 * @description make a withdrawal
 * @see https://docs.gemini.com/rest-api/#withdraw-crypto-funds
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tag] memo / destination tag, required for currencies in options['withdrawTagRequiredCurrencies']
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Gemini) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan AsyncResult[Transaction] {
	ch := make(chan AsyncResult[Transaction], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Gemini) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var tagWithdrawTag *string = nil
	tagWithdrawTag, paramsWithdrawTag := this.HandleParamString(params, "tag")
	this.CheckAddress(address, code, tagWithdrawTag)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"currency": currency["id"],
		"amount":   amount,
		"address":  address,
	}

	r1 := <-this.PrivatePostV1WithdrawCurrency(this.Extend(request, paramsWithdrawTag))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//   for BTC
	//     {
	//         "address":"mi98Z9brJ3TgaKsmvXatuRahbFRUFKRUdR",
	//         "amount":"1",
	//         "withdrawalId":"02176a83-a6b1-4202-9b85-1c1c92dd25c4",
	//         "message":"You have requested a transfer of 1 BTC to mi98Z9brJ3TgaKsmvXatuRahbFRUFKRUdR. This withdrawal will be sent to the blockchain within the next 60 seconds."
	//     }
	//
	//   for ETH
	//     {
	//         "address":"0xA63123350Acc8F5ee1b1fBd1A6717135e82dBd28",
	//         "amount":"2.34567",
	//         "txHash":"0x28267179f92926d85c5516bqc063b2631935573d8915258e95d9572eedcc8cc"
	//     }
	//
	//   for error (other variations of error messages are also expected)
	//     {
	//         "result":"error",
	//         "reason":"CryptoAddressWhitelistsNotEnabled",
	//         "message":"Cryptocurrency withdrawal address whitelists are not enabled for account 24. Please contact support@gemini.com for information on setting up a withdrawal address whitelist."
	//     }
	//
	var result *string = this.SafeString(response, "result")
	if result != nil && *result == "error" {
		panic(ExchangeError(this.Id + " withdraw() failed: " + this.Json(response)))
	}

	ch <- AsyncResult[Transaction]{Value: this.ParseTransaction(response, currency)}
	return nil
}
func (this *Gemini) Nonce() int64 {
	var nonceMethod string = *this.SafeString(this.Options, "nonce", "milliseconds")
	if nonceMethod == "milliseconds" {
		return this.Milliseconds()
	}
	return this.Seconds()
}

/**
 * @method
 * @name gemini#fetchDepositsWithdrawals
 * @description fetch history of deposits and withdrawals
 * @see https://docs.gemini.com/rest-api/#transfers
 * @param {string} [code] unified currency code for the currency of the deposit/withdrawals, default is undefined
 * @param {int} [since] timestamp in ms of the earliest deposit/withdrawal, default is undefined
 * @param {int} [limit] max number of deposit/withdrawals to return, default is undefined
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a list of [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Gemini) FetchDepositsWithdrawalsAsync(optionalArgs ...any) <-chan AsyncResult[[]Transaction] {
	ch := make(chan AsyncResult[[]Transaction], 1)
	go this.fetchDepositsWithdrawalsBody(ch, optionalArgs...)
	return ch
}
func (this *Gemini) fetchDepositsWithdrawalsBody(ch chan AsyncResult[[]Transaction], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var request map[string]any = map[string]any{}
	if limit != nil {
		request["limit_transfers"] = limit
	}
	if since != nil {
		request["timestamp"] = since
	}

	listEp2525 := <-this.PrivatePostV1Transfers(this.Extend(request, params))
	if listEp2525.Err != nil {
		panic(listEp2525.Err)
	}
	var response []any = listEp2525.Value

	ch <- AsyncResult[[]Transaction]{Value: TransactionsFromList(this.ParseTransactions(response))}
	return nil
}
func (this *Gemini) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// withdraw
	//
	//   for BTC
	//     {
	//         "address":"mi98Z9brJ3TgaKsmvXatuRahbFRUFKRUdR",
	//         "amount":"1",
	//         "withdrawalId":"02176a83-a6b1-4202-9b85-1c1c92dd25c4",
	//         "message":"You have requested a transfer of 1 BTC to mi98Z9brJ3TgaKsmvXatuRahbFRUFKRUdR. This withdrawal will be sent to the blockchain within the next 60 seconds."
	//     }
	//
	//   for ETH
	//     {
	//         "address":"0xA63123350Acc8F5ee1b1fBd1A6717135e82dBd28",
	//         "amount":"2.34567",
	//         "txHash":"0x28267179f92926d85c5516bqc063b2631935573d8915258e95d9572eedcc8cc"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.SafeInteger(transaction, "timestampms")
	var currencyId *string = this.SafeString(transaction, "currency")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var address *string = this.SafeString(transaction, "destination")
	var typeVar *string = this.SafeStringLower(transaction, "type")
	// if status field is available, then it's complete
	var statusRaw *string = this.SafeString(transaction, "status")
	var fee map[string]any = nil
	var feeAmount *float64 = this.SafeNumber(transaction, "feeAmount")
	if feeAmount != nil {
		fee = map[string]any{
			"cost":     feeAmount,
			"currency": code,
		}
	}
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          this.SafeString2(transaction, "eid", "withdrawalId"),
		"txid":        this.SafeString(transaction, "txHash"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"address":     address,
		"addressTo":   nil,
		"addressFrom": nil,
		"tag":         nil,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.SafeNumber(transaction, "amount"),
		"currency":    code,
		"status":      this.ParseTransactionStatus(statusRaw),
		"updated":     nil,
		"internal":    nil,
		"comment":     this.SafeString(transaction, "message"),
		"fee":         fee,
	})
}
func (this *Gemini) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"Advanced": "ok",
		"Complete": "ok",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Gemini) ParseDepositAddress(depositAddress any, optionalArgs ...any) DepositAddress {
	//
	//      {
	//          "address": "0xed6494Fe7c1E56d1bd6136e89268C51E32d9708B",
	//          "timestamp": "1636813923098",
	//          "addressVersion": "eV1"                                         }
	//      }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var address *string = this.SafeString(depositAddress, "address")
	var code *string = this.SafeCurrencyCode(nil, currency)
	return DepositAddressFromMap(map[string]any{
		"currency": code,
		"network":  nil,
		"address":  address,
		"tag":      nil,
		"info":     depositAddress,
	})
}

/**
 * @method
 * @name gemini#fetchDepositAddress
 * @see https://docs.gemini.com/rest-api/#get-deposit-addresses
 * @description fetch the deposit address for a currency associated with this account
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the endpoint
 * @param {string} [params.network]  *required* The chain of currency
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Gemini) FetchDepositAddressAsync(code string, optionalArgs ...any) <-chan AsyncResult[DepositAddress] {
	ch := make(chan AsyncResult[DepositAddress], 1)
	go this.fetchDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Gemini) fetchDepositAddressBody(ch chan AsyncResult[DepositAddress], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.FetchDepositAddressesByNetworkAsync(code, params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var indexedByNetwork map[string]any = StructResultMap(r1.Value, DepositAddressMapToMap)
	networkCode, _ := this.HandleNetworkCodeAndParams(params)

	ch <- AsyncResult[DepositAddress]{Value: DepositAddressFromMap(this.SafeDictMap(indexedByNetwork, networkCode))}
	return nil
}

/**
 * @method
 * @name gemini#fetchDepositAddressesByNetwork
 * @description fetch a dictionary of addresses for a currency, indexed by network
 * @see https://docs.gemini.com/rest-api/#get-deposit-addresses
 * @param {string} code unified currency code of the currency for the deposit address
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.network]  *required* The chain of currency
 * @returns {object} a dictionary of [address structures]{@link https://docs.ccxt.com/?id=address-structure} indexed by the network
 */
func (this *Gemini) FetchDepositAddressesByNetworkAsync(code string, optionalArgs ...any) <-chan AsyncResult[map[string]DepositAddress] {
	ch := make(chan AsyncResult[map[string]DepositAddress], 1)
	go this.fetchDepositAddressesByNetworkBody(ch, code, optionalArgs...)
	return ch
}
func (this *Gemini) fetchDepositAddressesByNetworkBody(ch chan AsyncResult[map[string]DepositAddress], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	var codeValue *string = SafeStringPtr(currency["code"])
	networkCode, paramsNetworkCode := this.HandleNetworkCodeAndParams(params)
	if networkCode == nil {
		panic(ArgumentsRequired(this.Id + " fetchDepositAddresses() requires a network parameter"))
	}
	var networkId any = this.NetworkCodeToId(networkCode, this.SafeString(currency, "code"))
	var request map[string]any = map[string]any{
		"network": networkId,
	}

	listEp2686 := <-this.PrivatePostV1AddressesNetwork(this.Extend(request, paramsNetworkCode))
	if listEp2686.Err != nil {
		panic(listEp2686.Err)
	}
	var response []any = listEp2686.Value
	var results []any = this.ParseDepositAddresses(response, []any{codeValue}, false, map[string]any{
		"network":  networkCode,
		"currency": codeValue,
	})

	// one address structure per network, like every other venue (the endpoint is scoped to a
	// single network, so the last address the venue lists for it wins — same as before)
	ch <- AsyncResult[map[string]DepositAddress]{Value: DepositAddressMapFromMap(this.IndexBy(results, "network"))}
	return nil
}
func (this *Gemini) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var url string = "/" + this.ImplodeParams(path, params)
	var query any = this.Omit(params, this.ExtractParams(path))
	var headersSigned map[string]any = nil
	if apiName == "private" {
		this.CheckRequiredCredentials()
		if strings.Index(this.ApiKey, "account") < 0 {
			panic(AuthenticationError(this.Id + " sign() requires an account-key, master-keys are not-supported"))
		}
		// gemini rejects a nonce that is not greater than the previously used one (InvalidNonce)
		var nonceValue int64 = this.IncrementingNonce()
		var nonce *string = this.NumberToString(nonceValue)
		var finalUrl string = url
		var request map[string]any = this.Extend(map[string]any{
			"request": finalUrl,
			"nonce":   nonce,
		}, query)
		var payload string = this.Json(request)
		payload = this.StringToBase64(payload)
		var signature string = this.Hmac(this.Encode(payload), this.Encode(this.Secret), sha384)
		headersSigned = map[string]any{
			"Content-Type":       "text/plain",
			"X-GEMINI-APIKEY":    this.ApiKey,
			"X-GEMINI-PAYLOAD":   payload,
			"X-GEMINI-SIGNATURE": signature,
		}
	} else {
		if !(this.IsEmpty(query)) {
			url += "?" + this.Urlencode(query)
		}
	}
	var apiUrl *string = this.SafeString(this.Urls["api"], apiName)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var fullUrl string = *apiUrl + url
	var bodyResolved *string = nil
	if (method == "POST") || (method == "DELETE") {
		jsonText := this.Json(query)
		bodyResolved = &jsonText
	}
	return map[string]any{
		"url":     fullUrl,
		"method":  method,
		"body":    bodyResolved,
		"headers": headersSigned,
	}
}
func (this *Gemini) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		if true {
			var feedback string = this.Id + " " + body
			this.ThrowBroadlyMatchedException(this.Exceptions["broad"], body, feedback)
		}
		return nil // fallback to default error handler
	}
	//
	//     {
	//         "result": "error",
	//         "reason": "BadNonce",
	//         "message": "Out-of-sequence nonce <1234> precedes previously used nonce <2345>"
	//     }
	//
	var result *string = this.SafeString(response, "result")
	if result != nil && *result == "error" {
		var reasonInner *string = this.SafeString(response, "reason")
		var message *string = this.SafeString(response, "message")
		var feedback *string = SafeStringPtr(Add(this.Id+" ", message))
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], reasonInner, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

